<span class="line"><span style="color:#C678DD;">    wire</span><span style="color:#ABB2BF;"> en2 = ~A[</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">];     </span><span style="color:#7F848E;font-style:italic;">// 低位片使能</span></span>
